"""Confirmed email input; unresolved operational points remain review-only."""
from copy import deepcopy
from policies import BUSINESS, PAGES as ORIGINAL, QUESTIONS as ORIGINAL_QUESTIONS

PAGES = deepcopy(ORIGINAL)
RIGHTS = 'Nothing in this policy excludes a refund or other remedy required by applicable law, including for non-delivery, deficient service or misrepresentation.'

def replace(slug, key, title, body):
    entries = PAGES[slug]['sections']
    assert any(row[0] == key for row in entries), (slug, key)
    PAGES[slug]['sections'] = [(k, title, body) if k == key else (k, t, b) for k, t, b in entries]

replace('terms-and-conditions','booking','Enquiries, booking and payment', '''<p>An enquiry does not confirm a booking. The full fee is payable before a booking is confirmed. NNG accepts UPI, bank transfer and payment links and issues the bill or invoice. The team confirms the appointment, format, scope, total fee including applicable taxes and official payment recipient in writing before payment. These review pages do not collect payment directly.</p><p>NNG's commercial policy is that client cancellations are non-refundable, subject to applicable law. The applicable terms must be disclosed before payment. Never share a banking password, card security code or OTP. Submitting an enquiry does not authorise recurring payments or automatic renewal.</p>''')
replace('terms-and-conditions','programme','Personalised Hand Holding Program', '''<p>The Personalised Hand Holding Program is described as a six-month engagement. The start and end dates and included work must be confirmed in writing before enrolment. It includes one scheduled conversation each month, by call or face to face as agreed, plus unlimited messages and recorded replies during the agreed tenure.</p><p>Unlimited messages and recorded replies do not mean unlimited live sessions, immediate replies, 24-hour availability or emergency support. Communication channels, response hours and expected reply times remain to be confirmed. Clients are expected to commit to the agreed tenure. Pause arrangements and the exact early-exit and unused-session treatment require confirmation before enrolment; do not assume a settled rule for these cases.</p><p>If NNG cannot continue the program, the resolution must be addressed under the agreed terms and applicable law. No automatic renewal is implied.</p>''')
replace('terms-and-conditions','products','Products: arrangements deferred', '''<p>NNG is currently prioritising consultations. Product-selling, delivery, return and refund arrangements for gemstones, Rudraksha and crystals are not yet finalised. A catalogue or basket does not establish an approved product-sale process. These consultation cancellation terms must not be treated as product-return terms.</p><p>Before accepting product payments or orders, NNG must confirm the seller, exact product, material and treatment disclosures, certification where applicable, total price, shipping and returns. Existing lawful rights for any already accepted order remain unaffected.</p>''')
replace('terms-and-conditions','cancellation','Changes, cancellations and complaints', f'''<p>Under NNG's commercial policy, a client who cancels a consultation does not receive a refund. If Narayani cannot attend a scheduled session, the team will arrange a replacement appointment with the client. {RIGHTS}</p><p>Client-requested rescheduling, notice periods, late arrival, missed sessions, technical failures and the process if no suitable replacement appointment can be agreed remain under review. These rules must be explained before payment; this draft does not invent a no-show charge or a right to unlimited rescheduling. See the <a href="../cancellation-refunds/">Cancellation, Returns &amp; Delivery page</a>.</p>''')

PAGES['cancellation-refunds']['summary'] = ['The full fee is payable before booking confirmation.', 'Client cancellations are non-refundable under NNG’s commercial policy, subject to applicable law.', 'Some rescheduling, programme and privacy arrangements remain under review.']
replace('cancellation-refunds','status','Current review status', '''<p>This draft incorporates NNG's confirmed full-payment requirement and commercial no-refund policy for client cancellations. It also records the monthly contact format for the Hand Holding Program. Outstanding cases are explicitly marked below.</p><p>These pages do not collect payment. The final terms must be explained before a new booking is paid for. This review does not retrospectively replace an existing client agreement. Existing terms and applicable law remain relevant.</p>''')
replace('cancellation-refunds','sessions','Consultations: changes, cancellations and no-shows', f'''<p>If a client cancels a consultation, NNG's commercial policy is that the fee is not refunded. If Narayani cannot attend the scheduled session, NNG will arrange a replacement appointment with the client.</p><p>{RIGHTS}</p><div class="pending"><strong>Still awaiting confirmation</strong><p>Client-requested rescheduling: required notice and permitted changes. Late arrival and missed sessions. Technical or connection failures. The resolution where NNG cannot deliver the session or no suitable replacement appointment can be agreed.</p></div><p>For a change request, contact the team promptly with the booking reference, appointment date and time zone. This draft does not create an automatic no-show forfeiture or an unlimited rescheduling entitlement.</p>''')
replace('cancellation-refunds','programme','Hand Holding Program: contact, commitment and changes', f'''<p>The six-month program includes one scheduled conversation per month, by call or face to face as agreed, plus unlimited messages and recorded replies during the agreed tenure. Unlimited messaging does not promise instant responses, unlimited live sessions, 24/7 support or emergency care.</p><p>NNG expects clients to commit to the full agreed tenure. This reply does not settle all pause, early-exit or unused-session cases. The written program confirmation must explain those rules before enrolment.</p><div class="pending"><strong>Still awaiting confirmation</strong><p>Communication channels, contact hours and expected response time; whether pauses are allowed; exact early-exit and unused-session treatment; exceptional circumstances; and what happens if NNG cannot continue.</p></div><p>{RIGHTS} An enquiry does not authorise automatic renewal or recurring charges.</p>''')
replace('cancellation-refunds','products','Products: returns not yet finalised', '''<p>NNG is currently focusing on consultations. Product sale and return arrangements will be addressed separately before product transactions are activated. Consultation cancellation terms do not establish a no-return policy for products.</p><div class="pending"><strong>Deferred until the product offering is ready</strong><p>Seller and invoicing responsibility, product disclosures, return address, change-of-mind rules, damaged or incorrect items, return shipping, replacements and refunds.</p></div><p>Any already accepted order remains subject to its agreed terms and applicable consumer rights.</p>''')
replace('cancellation-refunds','delivery','Product delivery: arrangements deferred', '''<p>Delivery regions, dispatch estimates, charges, courier partners, tracking, transit damage, loss and international shipping arrangements are not yet approved. No delivery commitment is created by these review pages. Product payments or orders should not be accepted until the relevant terms are confirmed and disclosed.</p>''')
replace('privacy-policy','recipients','Who may receive information', '''<p>NNG has stated that internal access to client information is limited to Team NNG. That does not establish that messaging, email, payment, cloud-storage or report-generation providers never process the information. The actual systems, authorised staff roles and provider access still need to be documented before the final policy takes effect.</p><p>Only information necessary for the agreed purpose should be shared. NNG's reply about reports does not confirm whether sessions are recorded or which AI tools, if any, receive client information. No assurance that data stays only with NNG or only in India is made by this draft.</p><div class="pending"><strong>Privacy arrangements still to confirm</strong><p>Storage and service providers; access permissions; retention and deletion periods; session recording; AI or report-generation tools and the data they receive; purposes, safeguards and required client permissions.</p></div><p>Booking does not automatically authorise session recording, advertising use, model training or unrelated processing. Where recording or AI/report processing is proposed, the specific purpose, relevant provider and information involved must be explained beforehand, with any required consent obtained.</p>''')
replace('privacy-policy','updates','Contact and policy updates', '''<p>General contact: <a href="mailto:enquiry@nngarg.com">enquiry@nngarg.com</a> or <a href="tel:+919205511101">+91 92055 11101</a>. Team NNG handles privacy grievances and other complaints internally, by email only at <a href="mailto:enquire@nngarg.com">enquire@nngarg.com</a>. Formal response, escalation arrangements and any legally required individual designation remain to be finalised.</p><p>Review draft updated 17 October 2026. A final version must state its effective date and explain material changes before new uses of information begin. The earlier technical website check was dated 15 October 2026 and is not a certification of later tracking changes.</p>''')
QUESTIONS = [
 ('Client changes and missed sessions', 'What happens if a client reschedules, is late, misses the session or loses internet access? How much notice is needed?'),
 ('NNG cannot deliver', 'What resolution is offered if no suitable replacement appointment can be agreed or NNG cannot finish a program?'),
 ('Hand Holding details', 'Which channels, days/hours and expected reply time apply? Can a program be paused? Confirm early-exit and unused-session rules.'),
 ('Privacy arrangements', 'Where are records stored, who can access them, which tools generate reports, are sessions recorded, what client data reaches AI tools, and when is information deleted?'),
 ('Final review', 'Confirm formal complaint response/escalation arrangements and obtain legal review before activation. Product rules are deferred until product sales are ready.'),
]

# Keep public review copy focused on the policy, not the internal email exchange.
for page in PAGES.values():
    page['sections'] = [(key, title, body.replace(
        'This reply does not settle all pause, early-exit or unused-session cases.',
        'Pause, early-exit and unused-session arrangements are not yet finalised.'
    ).replace(
        "NNG's reply about reports does not confirm whether sessions are recorded or which AI tools, if any, receive client information.",
        'Session recording and the use of any AI or report-generation tools are not yet confirmed. The final notice must identify any relevant tools, purposes and data involved.'
    )) for key, title, body in page['sections']]
